B.ac1=new A.dO("\u092d\u0930\u094d\u0917\u094b \u0926\u0947\u0935\u0938\u094d\u092f \u0927\u0940\u092e\u0939\u093f \u0964","\u0cad\u0cb0\u0ccd\u0c97\u0ccb \u0ca6\u0cc7\u0cb5\u0cb8\u0ccd\u0caf \u0ca7\u0cc0\u0cae\u0cb9\u0cbf \u0964","bhargo devasya dh\u012bmahi |","the radiance of the divine \u2014 we meditate on it.","\u0c86 \u0ca6\u0cc7\u0cb5\u0ca8 \u0ca4\u0cc7\u0c9c\u0cb8\u0ccd\u0cb8\u0ca8\u0ccd\u0ca8\u0cc1 \u0ca7\u0ccd\u0caf\u0cbe\u0ca8\u0cbf\u0cb8\u0ccb\u0ca3.",0)
B.abE=new A.dO("\u0927\u093f\u092f\u094b \u092f\u094b \u0928\u0903 \u092a\u094d\u0930\u091a\u094b\u0926\u092f\u093e\u0924\u094d \u0965","\u0ca7\u0cbf\u0caf\u0ccb \u0caf\u0ccb \u0ca8\u0c83 \u0caa\u0ccd\u0cb0\u0c9a\u0ccb\u0ca6\u0caf\u0cbe\u0ca4\u0ccd \u0965","dhiyo yo na\u1e25 pracoday\u0101t ||","May it awaken our minds.","\u0c85\u0ca6\u0cc1 \u0ca8\u0cae\u0ccd\u0cae \u0cac\u0cc1\u0ca6\u0ccd\u0ca7\u0cbf\u0caf\u0ca8\u0ccd\u0ca8\u0cc1 \u0caa\u0ccd\u0cb0\u0cc7\u0cb0\u0cc7\u0caa\u0cbf\u0cb8\u0cb2\u0cbf.",0)
