B.abI=new A.dO("\u0938\u0939 \u0935\u0940\u0930\u094d\u092f\u0902 \u0915\u0930\u0935\u093e\u0935\u0939\u0948 \u0964","\u0cb8\u0cb9 \u0cb5\u0cc0\u0cb0\u0ccd\u0caf\u0c82 \u0c95\u0cb0\u0cb5\u0cbe\u0cb5\u0cb9\u0cc8 \u0964","saha v\u012brya\u1e43 karav\u0101vahai |","May we work together with strength.","\u0c92\u0c9f\u0ccd\u0c9f\u0cbf\u0c97\u0cc6 \u0cb6\u0c95\u0ccd\u0ca4\u0cbf\u0caf\u0cbf\u0c82\u0ca6 \u0c95\u0cc6\u0cb2\u0cb8 \u0cae\u0cbe\u0ca1\u0ccb\u0ca3.",0)
B.abQ=new A.dO("\u0924\u0947\u091c\u0938\u094d\u0935\u093f \u0928\u093e\u0935\u0927\u0940\u0924\u092e\u0938\u094d\u0924\u0941 \u0964","\u0ca4\u0cc7\u0c9c\u0cb8\u0ccd\u0cb5\u0cbf \u0ca8\u0cbe\u0cb5\u0ca7\u0cc0\u0ca4\u0cae\u0cb8\u0ccd\u0ca4\u0cc1 \u0964","tejasvi n\u0101vadh\u012btamastu |","May our study be bright.","\u0ca8\u0cae\u0ccd\u0cae \u0c85\u0ca7\u0ccd\u0caf\u0caf\u0ca8 \u0ca4\u0cc7\u0c9c\u0cb8\u0ccd\u0cb5\u0cbf\u0caf\u0cbe\u0c97\u0cb2\u0cbf.",0)
B.ac_=new A.dO("\u092e\u093e \u0935\u093f\u0926\u094d\u0935\u093f\u0937\u093e\u0935\u0939\u0948 \u0964","\u0cae\u0cbe \u0cb5\u0cbf\u0ca6\u0ccd\u0cb5\u0cbf\u0cb7\u0cbe\u0cb5\u0cb9\u0cc8 \u0964","m\u0101 vidvi\u1e63\u0101vahai |","May we never dislike each other.","\u0ca8\u0cae\u0ccd\u0cae\u0cb2\u0ccd\u0cb2\u0cbf \u0ca6\u0ccd\u0cb5\u0cc7\u0cb7 \u0cac\u0cbe\u0cb0\u0ca6\u0cbf\u0cb0\u0cb2\u0cbf.",0)
